CREATE TABLE v187581 (v187582 INT DEFAULT 1) AS SELECT SUBSTRING('1', DAY(FROM_UNIXTIME(-1))) AS x2, LEFT('1', DAY(FROM_UNIXTIME(-1))) AS x3, RIGHT('1', DAY(FROM_UNIXTIME(-1))) AS x4, REPEAT('1', DAY(FROM_UNIXTIME(-1))) AS x5, RPAD('hi', DAY(FROM_UNIXTIME(-1)), '?') AS x6, LPAD('hi', DAY(FROM_UNIXTIME(-1)), '?') AS x7